function mrseo_ads_position_hero($slug){
 $copy=mrseo_ads_position_copy($slug);
 if(!$copy)return;
 ?>
 <a class="mrseo-ads-position-link" href="#mrseo-ads-approach"><?php echo esc_html($copy['hero']);?> <span aria-hidden="true">↓</span></a>
 <?php
}
function mrseo_ads_position_render($slug){
 $copy=mrseo_ads_position_copy($slug);
 if(!$copy)return;
 $hub=$slug==='google-ads';
 ?>
 <section class="mrseo-ads-position<?php echo $hub?' mrseo-ads-position-hub':'';?>" id="mrseo-ads-approach" aria-labelledby="mrseo-ads-position-title">
  <div class="pti-wrap mrseo-ads-position-wrap">
   <div class="mrseo-ads-position-intro">
    <span class="mrseo-ads-position-kicker">МИ ПРАЦЮЄМО ІНАКШЕ</span>
    <h2 id="mrseo-ads-position-title"><?php echo esc_html($copy['headline'][0]);?> <em><?php echo esc_html($copy['headline'][1]);?></em></h2>
    <p class="mrseo-ads-position-motto">Без пафосу. Без переплат. <em>По суті.</em></p>
   </div>
   <div class="mrseo-ads-position-items">
    <?php foreach($copy['items'] as $item):?>
    <div class="mrseo-ads-position-item"><h3><?php echo esc_html($item[0]);?></h3><p><?php echo esc_html($item[1]);?></p></div>
    <?php endforeach;?>
   </div>
   <p class="mrseo-ads-position-close"><?php echo esc_html($copy['close']);?></p>
  </div>
 </section>
 <?php
}
